command:
$ErrorActionPreference = "Stop"
git fetch origin main work/filter-presets --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
if ((git rev-parse origin/main).Trim() -ne "591ecbad86a133812fa27521ca771aaba15e2ffe") { throw "main moved" }

git checkout main
if ($LASTEXITCODE -ne 0) { throw "checkout main failed" }
git merge --ff-only origin/main
if ($LASTEXITCODE -ne 0) { throw "main fast-forward failed" }

$changed = @(git diff --name-only 1fc808f91fa2236890a0025a555ccbd0d922319c..HEAD -- app/winui src/base)
if ($changed.Count -ne 0) {
  $changed | ForEach-Object { Write-Host $_ }
  throw "current main product sources differ from last validated Search v2 binary"
}
if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) {
  throw "validated Release binary missing"
}

cmd /c "git show origin/work/filter-presets:tests/winui/test_filter_preset_gui.py > logs\filter-preset-gui.py"
if ($LASTEXITCODE -ne 0) { throw "baseline fixture materialization failed" }
$env:PYTHONPATH = "C:\dev\flyExplorer\tests\winui"
$env:FLY_MIGRATION_CONFIGURATION = "Release"
$env:FLY_FILTER_PRESET_BASELINE = "YES"
$env:FLY_FILTER_PRESET_SCREENSHOT = "C:\dev\flyExplorer\logs\filter-preset-before.png"
python -X utf8 logs\filter-preset-gui.py
if ($LASTEXITCODE -ne 0) { throw "baseline capture failed" }
Remove-Item Env:FLY_FILTER_PRESET_BASELINE

git checkout work/filter-presets
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/filter-presets
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

Write-Host "SOURCE_CONTRACTS"
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }

Write-Host "M20_NATIVE_RELEASE"
cmd /c tests\winui\m20\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M20 Release build failed" }
cmd /c "set FLY_M20_CONFIG=Release&& python -X utf8 tests\winui\m20\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M20 native fixture failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "FILTER_PRESET_GUI"
$env:FLY_FILTER_PRESET_SCREENSHOT = "C:\dev\flyExplorer\logs\filter-preset-after.png"
python -X utf8 tests\winui\test_filter_preset_gui.py
if ($LASTEXITCODE -ne 0) { throw "filter preset GUI failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

python -X utf8 -c "from PIL import Image; Image.open(r'logs\filter-preset-before.png').convert('RGB').save(r'logs\filter-preset-before.jpg',quality=78); Image.open(r'logs\filter-preset-after.png').convert('RGB').save(r'logs\filter-preset-after.jpg',quality=78)"
python -X utf8 -c "import base64,pathlib; p=pathlib.Path(r'logs\filter-preset-before.jpg'); s=base64.b64encode(p.read_bytes()).decode(); print('FILTER_BEFORE_B64_BEGIN'); [print(s[i:i+4096]) for i in range(0,len(s),4096)]; print('FILTER_BEFORE_B64_END')"
python -X utf8 -c "import base64,pathlib; p=pathlib.Path(r'logs\filter-preset-after.jpg'); s=base64.b64encode(p.read_bytes()).decode(); print('FILTER_AFTER_B64_BEGIN'); [print(s[i:i+4096]) for i in range(0,len(s),4096)]; print('FILTER_AFTER_B64_END')"

Write-Host "FILTER_PRESET_PREMAIN_PASS"
